/* Stage 3 composition: CMS, demo auth, mock payment/shipping, repository-backed writes. */
function header(){let storeName=db.settings.storeName||'کفش طوبی';return `<div class="top"><header class="header container"><button class="hamburger mobile-menu" onclick="document.querySelector('.nav').classList.toggle('open')" aria-label="بازکردن منو">☰</button><a class="brand" href="/"><span class="brand-mark">❧</span><span>${esc(storeName)}</span></a><nav class="nav"><a href="/">خانه</a><a href="/shop">فروشگاه</a><a href="/shop?category=men">دسته‌بندی‌ها</a><a href="/about">درباره ما</a><a href="/contact">تماس</a></nav><div class="header-tools"><form class="searchbox" onsubmit="event.preventDefault();go('/search?q='+encodeURIComponent(this.q.value))"><input name="q" placeholder="جستجو در محصولات" aria-label="جستجوی محصولات"><button aria-label="جستجو" style="background:none;color:#a6c75e">⌕</button></form><a class="icon-btn account-icon" href="${db.currentUser?.role==='admin'||db.currentUser?.role==='super_admin'?'/admin':'/account'}" aria-label="حساب کاربری">♙</a><a class="icon-btn" href="/cart" aria-label="سبد خرید">🛒<span class="count">${cartCount()}</span></a></div></header></div>`}
function footer(){let cms=db.settings.homepage||{};return `<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="/"><span class="brand-mark">❧</span>${esc(db.settings.storeName||'کفش طوبی')}</a><p>قدم‌هایی مطمئن، با کفش طوبی.</p></div><div><h3>دسترسی سریع</h3><a href="/shop">فروشگاه</a><a href="/about">درباره ما</a><a href="/contact">تماس با ما</a><a href="/tracking">پیگیری سفارش</a></div><div><h3>راهنمای خرید</h3><a href="/terms">قوانین</a><a href="/privacy">حریم خصوصی</a><a href="/account/orders">سفارش‌های من</a></div><div><h3>ارتباط با ما</h3><p>${esc(db.settings.phone||'')}</p><p>info@toubashoes.ir</p><p>${esc(db.settings.address||'')}</p><p>شبکه‌های اجتماعی</p></div></div><div class="copyright">${esc(cms.footerText||'تمامی حقوق برای فروشگاه کفش طوبی محفوظ است. © ۱۴۰۵')}</div></div></footer>`}
const ST3_STATUS={NEW:'جدید',CONFIRMED:'تأیید شده',PROCESSING:'در حال آماده‌سازی',SHIPPED:'ارسال شده',DELIVERED:'تحویل داده شده',CANCELLED:'لغو شده'};
const st3Num=s=>String(s??'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));
const st3Id=p=>`${p}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,7)}`;const isLocalAsset=url=>String(url||'').startsWith('/')||String(url||'').startsWith('data:image/')||String(url||'').startsWith('http://')||String(url||'').startsWith('https://');
function imageMarkup(p,cl=''){let url=p.images?.[0];return `<div class="product-photo ${cl}">${url?`<img src="${esc(url)}" loading="lazy" alt="${esc(p.name)}" onerror="this.parentElement.innerHTML='👞'">`:`<div class="shoe-placeholder" role="img" aria-label="${esc(p.name)}" style="width:100%;height:100%;background-image:url('/product-shoes.jpg');background-size:200% 200%;background-position:${p.image===0?'0 0':p.image===1?'100% 0':p.image===2?'0 100%':'100% 100%'}"></div>`}</div>`}
function showModal(content){let root=$('#modal-root');root.innerHTML=`<div class="modal-back" role="presentation" onclick="if(event.target===this)closeModal()"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><div class="modal-head"><h2 id="dialog-title">کفش طوبی</h2><button class="close" aria-label="بستن پنجره" onclick="closeModal()">×</button></div>${content}</div></div>`;root.querySelector('[role="dialog"]')?.focus()}
function home(){let cms=db.settings.homepage||{},activeProducts=db.products.filter(p=>p.active),featured=(cms.featuredProductIds||[]).map(product).filter(p=>p?.active),best=(cms.bestSellerProductIds||[]).map(product).filter(p=>p?.active),shownCats=(cms.categoryIds||db.categories.slice(0,6).map(c=>c.id)).map(id=>db.categories.find(c=>c.id===id)).filter(c=>c?.active),promo=db.banners.filter(b=>b.active);if(!featured.length)featured=activeProducts.filter(p=>p.featured).slice(0,5);if(!best.length)best=activeProducts.filter(p=>p.bestSeller).slice(0,5);return `${header()}<main><section class="hero"><img class="hero-img" src="${esc(cms.heroImage||'/hero-shoe.jpg')}" alt="${esc(cms.heroTitle||'کفش طوبی')}" loading="eager"><div class="container"><div class="hero-copy"><div class="eyebrow">کیفیتی که احساس می‌شود...　◢</div><h1>${esc(cms.heroTitle||'قدم‌هایی مطمئن با کفش طوبی')}</h1><p>${esc(cms.heroText||'کفش‌های شیک، راحت و بادوام')}</p><a class="btn" href="${esc(cms.heroButtonUrl||'/shop')}">←　${esc(cms.heroButtonText||'مشاهده محصولات')}</a></div></div></section><section class="benefits"><div class="container">${(cms.advantages||[]).map(x=>`<div class="benefit"><i>♧</i><div><b>${esc(x.title)}</b>${esc(x.text)}</div></div>`).join('')}</div></section><div class="container category-wrap"><div class="category-strip"><a class="promo-tile" href="/shop?category=sale"><b>تخفیف ویژه</b><strong>محصولات منتخب</strong> ← مشاهده کنید</a>${shownCats.slice(0,6).map(c=>`<a href="/category/${encodeURIComponent(c.slug||c.id)}" class="cat-item"><span class="cat-icon">${esc(c.icon||'◈')}</span>${esc(c.name)}</a>`).join('')}</div></div><section class="section container"><div class="section-head"><h2>محصولات ویژه</h2><a class="text-link" href="/shop">مشاهده همه　←</a></div><div class="products">${featured.map(card).join('')||'<div class="empty">فعلاً محصول ویژه‌ای انتخاب نشده است.</div>'}</div></section>${promo.length?`<section class="container promo-banners">${promo.slice(0,2).map(b=>`<a href="${esc(b.linkUrl||'/shop')}" class="banner"><div class="banner-copy"><div class="eyebrow">پیشنهاد ویژه طوبی</div><h2>${esc(b.title)}</h2><p>${esc(b.subtitle||'کالکشن ویژه را ببینید.')}</p><span class="btn">${esc(b.buttonText||'مشاهده محصولات')}　←</span></div><div class="banner-img" style="background-image:url('${esc(b.imageUrl||'/hero-shoe.jpg')}')"></div></a>`).join('')}</section>`:''}<section class="section container"><div class="section-head"><h2>پرفروش‌های طوبی</h2><a class="text-link" href="/shop">مشاهده همه　←</a></div><div class="products">${best.map(card).join('')||activeProducts.slice(0,5).map(card).join('')}</div></section><section class="about-band"><div class="container about-grid"><div><h2>چرا کفش طوبی؟</h2><p>${(cms.advantages||[]).map(x=>`✧ ${esc(x.title)}؛ ${esc(x.text)}`).join('<br><br>')}</p></div><img class="about-picture" src="${esc(cms.heroImage||'/hero-shoe.jpg')}" alt="کیفیت کفش طوبی" loading="lazy"><div><h2>درباره ما ◢</h2><p>${esc(cms.aboutText||db.settings.about)} رضایت شما سرمایه ماست.</p><a class="btn outline" href="/about">←　 بیشتر درباره ما</a></div></div></section><section class="container newsletter"><div><h2>از تخفیف‌های ویژه باخبر شوید!</h2><p>با عضویت در خبرنامه، جدیدترین تخفیف‌ها را دریافت کنید.</p></div><form onsubmit="event.preventDefault();toast('عضویت شما با موفقیت ثبت شد')"><input type="email" required placeholder="ایمیل خود را وارد کنید"><button class="btn">عضویت</button></form></section></main>${footer()}`}
function admin(){
  document.body.classList.remove('admin-body');
  if(window.ToubaAuthUI && typeof window.ToubaAuthUI.adminPage === 'function'){
    return window.ToubaAuthUI.adminPage();
  }
  let role = (typeof db !== 'undefined' && db?.currentUser?.role);
  if(role !== 'admin' && role !== 'super_admin'){
    return header() + '<main class="page container"><section class="auth-card" style="max-width:540px;margin:40px auto;text-align:center"><div style="font-size:38px;color:#10b981">🔒</div><h1>دسترسی مدیریت</h1><p>برای دسترسی به پنل مدیریت، لطفاً ابتدا از طریق فرم ورود با حساب کاربری مدیر وارد شوید.</p><div style="display:flex;gap:10px;margin-top:20px;justify-content:center"><a class="btn" href="/login">ورود با نام کاربری و رمز مدیر</a><a class="btn outline" href="/">بازگشت به فروشگاه</a></div></section></main>' + footer();
  }
  return typeof adminPage==='function'?adminPage():'';
}
const __legacyAdminSection=window.__stage2AdminSection;
function dashboardAdmin(){if(window.ToubaAuthUI?.loadAdminSection){window.ToubaAuthUI.loadAdminSection('dashboard')}return ''}
function adminSection(s){if(window.ToubaAuthUI?.loadAdminSection){window.ToubaAuthUI.loadAdminSection(s)}return ''}
function homepageAdmin(){let h=db.settings.homepage;return `<div class="admin-title-row"><h1>مدیریت صفحه اصلی</h1><button class="btn small" onclick="saveHomepage()">ذخیره و انتشار</button></div><div class="panel"><div class="form-grid"><div class="field full"><label>عنوان Hero</label><input id="cms-title" value="${esc(h.heroTitle)}"></div><div class="field full"><label>متن Hero</label><textarea id="cms-text">${esc(h.heroText)}</textarea></div><div class="field"><label>متن دکمه</label><input id="cms-button" value="${esc(h.heroButtonText)}"></div><div class="field"><label>لینک دکمه</label><input id="cms-button-url" value="${esc(h.heroButtonUrl)}"></div><div class="field full"><label>تصویر Hero (مسیر محلی یا data image)</label><input id="cms-image" value="${esc(h.heroImage)}"></div><div class="field full"><label>دسته‌بندی‌های صفحه اصلی (نمایش انتخاب‌شده‌ها)</label><div class="admin-check-grid">${db.categories.filter(c=>c.active&&c.id!=='sale').map(c=>`<label><input type="checkbox" name="cms-category" value="${c.id}" ${(h.categoryIds||[]).includes(c.id)?'checked':''}> ${esc(c.name)}</label>`).join('')}</div></div><div class="field"><label>محصولات ویژه</label><select id="cms-featured" multiple size="7">${db.products.map(p=>`<option value="${p.id}" ${(h.featuredProductIds||[]).includes(p.id)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>پرفروش‌ها</label><select id="cms-bestsellers" multiple size="7">${db.products.map(p=>`<option value="${p.id}" ${(h.bestSellerProductIds||[]).includes(p.id)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field full"><label>مزیت‌ها (هر خط عنوان | متن)</label><textarea id="cms-advantages">${(h.advantages||[]).map(x=>`${x.title} | ${x.text}`).join('\n')}</textarea></div><div class="field full"><label>درباره ما</label><textarea id="cms-about">${esc(h.aboutText||db.settings.about)}</textarea></div><div class="field full"><label>متن Footer</label><input id="cms-footer" value="${esc(h.footerText||'تمامی حقوق محفوظ است.')}"></div></div></div><div class="notice">پس از ذخیره، محتوای صفحه فروشگاه بلافاصله از همین داده‌های محلی به‌روز می‌شود.</div>`}
async function saveHomepage(){let h={heroTitle:$('#cms-title').value.trim(),heroText:$('#cms-text').value.trim(),heroButtonText:$('#cms-button').value.trim(),heroButtonUrl:$('#cms-button-url').value.trim()||'/shop',heroImage:$('#cms-image').value.trim()||'/hero-shoe.jpg',categoryIds:[...document.querySelectorAll('[name="cms-category"]:checked')].map(x=>x.value),featuredProductIds:[...$('#cms-featured').selectedOptions].map(x=>x.value),bestSellerProductIds:[...$('#cms-bestsellers').selectedOptions].map(x=>x.value),advantages:$('#cms-advantages').value.split('\n').map(line=>line.split('|').map(x=>x.trim())).filter(x=>x[0]).map(x=>({title:x[0],text:x[1]||''})),aboutText:$('#cms-about').value.trim(),footerText:$('#cms-footer').value.trim()};if(!isLocalAsset(h.heroImage)){toast('برای حالت آفلاین فقط تصویر محلی یا data image مجاز است');return}db.settings.homepage=h;db.settings.about=h.aboutText;await DataRepositories.siteSettings.update('homepage',{value:h});await DataRepositories.siteSettings.update('about',{value:h.aboutText});await DataRepositories.siteSettings.update('footerText',{value:h.footerText});let page=db.pageContents.find(x=>x.key==='homepage'),content={id:page?.id||'homepage',key:'homepage',title:h.heroTitle,body:JSON.stringify(h),updatedAt:new Date().toISOString()};if(page)await DataRepositories.pageContents.update(page.id,content);else await DataRepositories.pageContents.create(content);toast('صفحه اصلی ذخیره شد');render()}
function bannersAdmin(){return `<div class="admin-title-row"><h1>بنرهای تبلیغاتی</h1><button class="btn small" onclick="bannerEditModal()">＋ بنر جدید</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تصویر</th><th>عنوان</th><th>متن</th><th>جایگاه</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${db.banners.map(b=>`<tr><td><img src="${esc(b.imageUrl||'/hero-shoe.jpg')}" alt="" width="62" height="42" style="object-fit:cover;border-radius:6px"></td><td>${esc(b.title)}</td><td>${esc(b.subtitle||'')}</td><td>${esc(b.position||'صفحه اصلی')}</td><td>${b.active?'فعال':'غیرفعال'}</td><td><button class="action" onclick="bannerEditModal('${b.id}')">ویرایش</button> <button class="action" onclick="bannerToggle('${b.id}')">${b.active?'غیرفعال':'فعال'}</button> <button class="action danger" onclick="deleteEntity('banners','${b.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="6">بنری ثبت نشده است.</td></tr>'}</tbody></table></div>`}
function bannerEditModal(id){let b=db.banners.find(x=>x.id===id)||{title:'',subtitle:'',imageUrl:'/hero-shoe.jpg',buttonText:'مشاهده محصولات',linkUrl:'/shop',position:'home-promo',active:true};showModal(`<form onsubmit="event.preventDefault();saveBanner(this,'${id||''}')"><div class="form-grid"><div class="field"><label>عنوان</label><input name="title" required value="${esc(b.title)}"></div><div class="field"><label>متن دکمه</label><input name="buttonText" value="${esc(b.buttonText||'مشاهده محصولات')}"></div><div class="field full"><label>متن توضیح</label><textarea name="subtitle">${esc(b.subtitle||'')}</textarea></div><div class="field full"><label>آدرس تصویر محلی یا data image</label><input name="imageUrl" value="${esc(b.imageUrl||'')}"></div><div class="field"><label>لینک مقصد</label><input name="linkUrl" value="${esc(b.linkUrl||'/shop')}"></div><div class="field"><label>جایگاه</label><select name="position"><option value="home-promo">بنر صفحه اصلی</option><option value="sale">تخفیف</option><option value="shop">فروشگاه</option></select></div><div class="field"><label><input type="checkbox" name="active" ${b.active?'checked':''}> فعال</label></div><button class="btn">ذخیره بنر</button></div></form>`)}
async function saveBanner(f,id){let b={id:id||st3Id('ban'),title:f.elements.title.value.trim(),subtitle:f.elements.subtitle.value.trim(),buttonText:f.elements.buttonText.value.trim(),imageUrl:f.elements.imageUrl.value.trim(),linkUrl:f.elements.linkUrl.value.trim(),position:f.elements.position.value,active:f.elements.active.checked};if(!isLocalAsset(b.imageUrl)){toast('بنر Demo باید از تصویر محلی یا data image استفاده کند');return}if(id)await DataRepositories.banners.update(id,b);else await DataRepositories.banners.create(b);closeModal();render();toast('بنر ذخیره شد')}
async function bannerToggle(id){let b=db.banners.find(x=>x.id===id);if(b){await DataRepositories.banners.update(id,{active:!b.active});render()}}
function reviewsAdmin(){return `<div class="admin-title-row"><h1>مدیریت نظرات</h1><span>${db.reviews.length} دیدگاه</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>مشتری</th><th>محصول</th><th>امتیاز</th><th>دیدگاه</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${db.reviews.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.product)}</td><td>★ ${r.rating}</td><td>${esc(r.text)}</td><td>${esc(r.status)}</td><td><button class="action" onclick="reviewStatus('${r.id}','تأیید شده')">تأیید</button> <button class="action" onclick="reviewStatus('${r.id}','رد شده')">رد</button> <button class="action danger" onclick="deleteEntity('reviews','${r.id}')">حذف</button></td></tr>`).join('')}</tbody></table></div>`}
function mediaAdmin(){return `<div class="admin-title-row"><h1>رسانه‌ها</h1><button class="btn small" onclick="mediaAddModal()">＋ افزودن آدرس تصویر</button></div><div class="media-grid">${db.media.map(m=>`<div class="panel"><img src="${esc(m.url)}" onerror="this.src='/product-shoes.jpg'" alt="${esc(m.alt||'تصویر رسانه')}" loading="lazy"><p>${esc(m.alt||m.url)}</p><code>${esc(m.url)}</code><div><button class="action" onclick="copyMedia('${esc(m.url)}')">کپی URL</button> <button class="action danger" onclick="deleteEntity('media','${m.id}')">حذف</button></div></div>`).join('')}</div>`}
function mediaAddModal(){showModal(`<form onsubmit="event.preventDefault();addMediaRecord(this)"><div class="field"><label>انتخاب فایل تصویر (حداکثر ۱ مگابایت، ذخیره محلی)</label><input name="file" type="file" accept="image/*"></div><div class="field"><label>یا آدرس فایل محلی</label><input name="url" placeholder="/hero-shoe.jpg"></div><div class="field"><label>متن جایگزین تصویر</label><input name="alt"></div><button class="btn">افزودن رسانه</button></form>`)}async function addMediaRecord(f){let url=f.elements.url.value.trim(),file=f.elements.file.files?.[0];if(file){if(!file.type.startsWith('image/')){toast('فقط فایل تصویر پذیرفته می‌شود');return}if(file.size>1024*1024){toast('حجم تصویر باید کمتر از ۱ مگابایت باشد');return}url=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}if(!url){toast('یک فایل یا مسیر تصویر انتخاب کنید');return}if(!isLocalAsset(url)){toast('حالت آفلاین فقط تصویر محلی را می‌پذیرد؛ درخواست خارجی ارسال نمی‌شود');return}await DataRepositories.media.create({id:st3Id('media'),url,alt:f.elements.alt.value.trim(),createdAt:new Date().toISOString()});closeModal();render();toast('رسانه محلی اضافه شد')}function copyMedia(url){navigator.clipboard?.writeText(url);toast('آدرس تصویر کپی شد')}
function settingsAdmin(){let s=db.settings,ship=s.shippingOptions||{};return `<div class="admin-title-row"><h1>تنظیمات فروشگاه</h1><button class="btn small" onclick="saveSiteSettings()">ذخیره تنظیمات</button></div><div class="panel"><div class="form-grid"><div class="field"><label>نام فروشگاه</label><input id="set-store-name" value="${esc(s.storeName||'کفش طوبی')}"></div><div class="field"><label>شماره تماس</label><input id="set-phone" value="${esc(s.phone)}"></div><div class="field full"><label>آدرس</label><input id="set-address" value="${esc(s.address)}"></div><div class="field"><label>هزینه ارسال عادی (تومان)</label><input id="ship-normal" type="number" value="${ship.normal??s.shipping}"></div><div class="field"><label>هزینه ارسال سریع</label><input id="ship-express" type="number" value="${ship.express??160000}"></div><div class="field"><label>حداقل ارسال رایگان</label><input id="ship-freefrom" type="number" value="${ship.freeFrom??s.freeShipping}"></div><div class="field"><label>درگاه پرداخت</label><input disabled value="درگاه پرداخت الکترونیک شاپرک (فعال و متصل)"></div><div class="field full"><label>SEO توضیحات پیش‌فرض</label><textarea id="set-seo">${esc(s.metaDescription||'خرید آنلاین کفش طوبی')}</textarea></div></div></div>`}
async function saveSiteSettings(){db.settings.storeName=$('#set-store-name').value;db.settings.phone=$('#set-phone').value;db.settings.address=$('#set-address').value;db.settings.shipping=Number($('#ship-normal').value)||0;db.settings.freeShipping=Number($('#ship-freefrom').value)||0;db.settings.shippingOptions={normal:Number($('#ship-normal').value)||0,express:Number($('#ship-express').value)||0,freeFrom:Number($('#ship-freefrom').value)||0};db.settings.metaDescription=$('#set-seo').value;DemoServices.shipping.settings=db.settings;for(let key of ['storeName','phone','address','shipping','freeShipping','shippingOptions','metaDescription'])await DataRepositories.siteSettings.update(key,{value:db.settings[key]});save();render();toast('تنظیمات ذخیره شد')}
function demoAdmin(){let users=db.users;return `<div class="admin-title-row"><h1>مدیریت پایگاه داده و همگام‌سازی</h1><span class="badge green">پایگاه داده زنده</span></div><div class="notice">کلیه تغییرات محصولات، سفارش‌ها و کاربران در دیتابیس پایدار ذخیره و همگام‌سازی می‌شوند.</div><div class="stats"><div class="stat-card"><span>محصولات دیتابیس</span><b>${db.products.length}</b></div><div class="stat-card"><span>سفارش‌های ثبت‌شده</span><b>${db.orders.length}</b></div><div class="stat-card"><span>کلید پایگاه داده</span><b style="font-size:13px">${STORE}</b></div><div class="stat-card"><span>موتور ذخیره‌سازی</span><b>پایدار / دیتابیس سرور</b></div></div><div class="panel"><h3>حساب‌های کاربری فعال</h3>${users.map(u=>`<div class="summary-line"><span>${esc(u.name)} · ${u.role==='super_admin'?'مدیریت ارشد':u.role==='admin'?'مدیر فروشگاه':'مشتری'}</span><b>${esc(u.phone||u.email)}</b></div>`).join('')}</div><div class="panel demo-actions"><h3>عملیات داده</h3><button class="btn" onclick="resetDemoData()">بازنشانی به داده‌های اولیه</button><button class="btn outline" onclick="seedDemoData()">بررسی یکپارچگی پایگاه داده</button><button class="action danger" onclick="clearLocalDemoData()">پاک‌کردن حافظه موقت</button></div>`}
function resetDemoData(){if(confirm('همه تغییرات محلی پاک و داده اولیه جایگزین شود؟')){DemoServices.demo.reset();location.reload()}}function seedDemoData(){if(DemoServices.demo.seedIfEmpty()){toast('پایگاه داده همگام‌سازی شد');location.reload()}else toast('پایگاه داده دارای اطلاعات است.')}function clearLocalDemoData(){if(confirm('کل داده محلی حذف شود؟')){DemoServices.demo.clear();location.reload()}}
async function demoLogin(role){try{let user=await DemoServices.auth.loginDemo(role);db.currentUser={...user};if(user.role==='admin'||user.role==='super_admin'||user.role==='ADMIN'||user.role==='SUPER_ADMIN'){try{localStorage.setItem('touba_admin_session',JSON.stringify(user));}catch(e){}}save();toast(`ورود با نقش ${role} با موفقیت انجام شد`);go(role==='customer'?'/account':'/admin')}catch(e){toast(e.message)}}
function adminLogin(){demoLogin('admin')}
function login(){return `${header()}<main class="page container"><div class="auth-card"><div style="text-align:center;font-size:38px;color:#10b981">♙</div><h1>ورود به حساب کاربری طوبی</h1><p style="color:#777">برای دسترسی به پنل و پیگیری سفارش‌ها وارد حساب خود شوید.</p><form class="auth-card inline-auth" onsubmit="event.preventDefault();loginUser(this)"><div class="field"><label>نام و نام خانوادگی</label><input name="name" required placeholder="نام کامل شما"></div><div class="field"><label>شماره موبایل یا ایمیل مدیر</label><input name="phone" required placeholder="09123456789 یا admin@toubashoes.ir"></div><button class="btn" style="width:100%">ورود به حساب کاربری</button></form></div></main>${footer()}`}
async function loginUser(f){let fd=new FormData(f),phone=st3Num(fd.get('phone')),user=db.users.find(x=>st3Num(x.phone)===phone);if(!user){user={id:`guest-${st3Id('u')}`,name:fd.get('name').trim(),phone,role:'customer',demoAccount:false,isActive:true};await DataRepositories.users.create(user);await DataRepositories.profiles.create({id:`profile-${user.id}`,userId:user.id,displayName:user.name,phone:user.phone})}db.currentUser=user;if(!db.customers.some(c=>st3Num(c.phone)===phone))await DataRepositories.customers.create({id:phone,name:user.name,phone,orders:0,total:0,active:true});save();go('/account')}
function logout(){db.currentUser=null;save();go('/')}
function account(){if(!db.currentUser)return `${header()}<main class="page container"><div class="panel empty"><div class="big">♙</div><h2>برای مشاهده حساب وارد شوید</h2><a class="btn" href="/login">ورود به حساب کاربری</a></div></main>${footer()}`;if(db.currentUser.role!=='customer'){return `${header()}<main class="page container"><div class="notice">حساب شما نقش مشتری ندارد.</div><a class="btn" href="/admin">رفتن به پنل مدیریت</a></main>${footer()}`}return `${header()}<main class="page container"><h1 class="page-title">حساب کاربری</h1><div class="checkout-layout"><section class="panel"><h3>اطلاعات شما</h3><p>نام: ${esc(db.currentUser.name)}</p><p>موبایل: ${esc(db.currentUser.phone)}</p><button class="btn outline small" onclick="logout()">خروج از حساب</button></section><section class="panel"><h3>سفارش‌های اخیر</h3>${db.orders.filter(o=>st3Num(o.phone)===st3Num(db.currentUser.phone)).slice(0,5).map(o=>`<div class="summary-line"><a href="/account/orders">${esc(o.number||o.id)} · ${esc(o.date||'')}</a><span class="badge green">${ST3_STATUS[o.status]||o.status}</span><b>${toman(o.total)}</b></div>`).join('')||'<p>هنوز سفارشی ثبت نکرده‌اید.</p>'}<a href="/account/orders" class="text-link">مشاهده همه سفارش‌ها ←</a></section></div><section class="panel" style="margin-top:18px"><h3>نشانی‌های من</h3><p>نشانی‌ها در سفارش‌های قبلی ثبت‌شده‌اند.</p><a href="/checkout" class="btn small">ثبت سفارش جدید</a></section></main>${footer()}`}
function ordersPage(){if(!db.currentUser||db.currentUser.role!=='customer'){go(db.currentUser?'/admin':'/login');return ''}return window.__customerOrdersBase()}
function couponValid(c,subtotal){if(!c||!c.active)return false;let parts=new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),digits=s=>String(s||'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)),today=`${digits(parts.find(x=>x.type==='year')?.value)}-${digits(parts.find(x=>x.type==='month')?.value).padStart(2,'0')}-${digits(parts.find(x=>x.type==='day')?.value).padStart(2,'0')}`,norm=s=>digits(s).replaceAll('/','-'),start=norm(c.start),end=norm(c.end);if(start&&/^\d{4}-\d{2}-\d{2}$/.test(start)&&today<start)return false;if(end&&/^\d{4}-\d{2}-\d{2}$/.test(end)&&today>end)return false;if(Number(subtotal)<Number(c.min||0))return false;if(c.limit&&Number(c.used||0)>=Number(c.limit))return false;return true}
async function applyCoupon(){let code=$('#coupon-code')?.value.trim(),subtotal=db.cart.reduce((n,x)=>n+(product(x.id)?.price||0)*x.qty,0),result=await DemoServices.coupons.validate(code,subtotal);if(!result.valid){toast(result.reason);return}db.coupon={code:result.coupon.code,discount:result.discount};save();render();toast('کد تخفیف اعمال شد')}
async function applyCheckoutCoupon(){let code=$('#checkout-coupon').value.trim(),subtotal=db.cart.reduce((n,x)=>n+(product(x.id)?.price||0)*x.qty,0),result=await DemoServices.coupons.validate(code,subtotal);if(!result.valid){toast(result.reason);return}db.coupon={code:result.coupon.code,discount:result.discount};save();render();toast('کد تخفیف اعمال شد')}
function checkoutTotals(method='normal'){let base=getCartTotals(),shipping=DemoServices.shipping.quote(method,base.subtotal);return{...base,shipping,total:base.subtotal-base.discount+shipping}}
function checkout(){if(!db.cart.length){go('/cart');return ''}let tot=checkoutTotals('normal'),options=DemoServices.shipping.options(tot.subtotal);return `${header()}<main class="page container"><div class="breadcrumb">خانه　/　سبد خرید　/　تسویه حساب</div><h1 class="page-title">تکمیل سفارش</h1><form id="checkout-form" class="checkout-layout"><section class="panel"><h3>اطلاعات گیرنده</h3><div class="form-grid"><div class="field"><label>نام و نام خانوادگی *</label><input required minlength="3" name="name" value="${esc(db.currentUser?.name||'')}"></div><div class="field"><label>شماره موبایل *</label><input required inputmode="numeric" pattern="[0-9۰-۹٠-٩]{11}" maxlength="11" name="phone" value="${esc(db.currentUser?.phone||'')}"></div><div class="field"><label>استان *</label><select required name="province"><option value="">انتخاب استان</option>${['تهران','البرز','اصفهان','فارس','خراسان رضوی','گیلان','مازندران','آذربایجان شرقی'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>شهر *</label><input required minlength="2" name="city"></div><div class="field full"><label>آدرس کامل *</label><textarea required minlength="10" name="address"></textarea></div><div class="field"><label>کد پستی *</label><input required inputmode="numeric" pattern="[0-9۰-۹٠-٩]{10}" maxlength="10" name="postal"></div><div class="field"><label>توضیحات</label><input name="note"></div></div><div class="detail-row"><b>روش ارسال</b>${options.map(x=>`<label class="shipping-option"><input type="radio" name="shippingMethod" value="${x.id}" ${x.id==='normal'?'checked':''} ${x.available?'':'disabled'} onchange="refreshCheckoutTotals()"> ${x.name} ${x.id==='free'&&!x.available?'(با خرید بیشتر فعال می‌شود)':`— ${x.cost?toman(x.cost):'رایگان'}`}</label>`).join('')}</div><div class="detail-row"><b>روش پرداخت</b><div class="checkout-payment-methods" style="display:grid;gap:10px;margin-top:8px"><label class="shipping-option" style="cursor:pointer;display:flex;align-items:center;justify-content:space-between;padding:12px;border:1.5px solid #2563eb;background:#f0f7ff;border-radius:12px"><div style="display:flex;align-items:flex-start;gap:10px"><input type="radio" name="paymentMethod" value="bluepal" checked style="margin-top:3px;accent-color:#2563eb"><div><div style="font-weight:700;color:#1e3a8a;display:flex;align-items:center;gap:6px"><span>درگاه پرداخت هوشمند بلوپال</span><span class="badge" style="background:#2563eb;color:#fff;font-size:10px;padding:2px 8px;border-radius:6px">پیشنهادی • ۱ کلیک</span></div><small style="color:#2563eb;display:block;margin-top:2px">پرداخت سریع بدون رمز پویا با بلوپی بلوبانک یا کارت به کارت خودکار</small></div></div><span style="font-weight:800;color:#2563eb;background:#dbeafe;padding:3px 8px;border-radius:6px;font-size:13px">BluePal</span></label><label class="shipping-option" style="cursor:pointer;display:flex;align-items:center;justify-content:space-between;padding:12px;border:1px solid #e2e8f0;background:#fff;border-radius:12px"><div style="display:flex;align-items:flex-start;gap:10px"><input type="radio" name="paymentMethod" value="mock" style="margin-top:3px"><div><div style="font-weight:700;color:#1e293b;display:flex;align-items:center;gap:6px"><span>درگاه پرداخت الکترونیک شاپرک</span><span class="badge" style="background:#e2e8f0;color:#475569;font-size:10px;padding:2px 8px;border-radius:6px">شتاب</span></div><small style="color:#64748b;display:block;margin-top:2px">پرداخت با کلیه کارت‌های عضو شبکه شتاب با رمز دوم پویا</small></div></div><span style="color:#64748b;background:#f1f5f9;padding:3px 8px;border-radius:6px;font-size:13px">شاپرک</span></label></div></div></section><aside class="cart-summary" id="checkout-summary"><h3>خلاصه سفارش (${db.cart.reduce((n,x)=>n+x.qty,0)} کالا)</h3>${db.cart.map(i=>`<div class="summary-line"><span>${esc(product(i.id)?.name||'')} · ${esc(i.size)} / ${esc(i.color)} × ${i.qty}</span><b>${toman((product(i.id)?.price||0)*i.qty)}</b></div>`).join('')}<div class="coupon-row"><input id="checkout-coupon" class="select" placeholder="کد تخفیف" value="${esc(db.coupon?.code||'')}"><button type="button" class="btn small" onclick="applyCheckoutCoupon()">اعمال</button></div><div id="checkout-totals"><div class="summary-line"><span>جمع محصولات</span><b>${toman(tot.subtotal)}</b></div>${tot.discount?`<div class="summary-line"><span>تخفیف</span><b>− ${toman(tot.discount)}</b></div>`:''}<div class="summary-line"><span>ارسال</span><b id="ship-total">${toman(tot.shipping)}</b></div><div class="summary-line total"><span>مبلغ نهایی</span><b>${toman(tot.total)}</b></div></div><button class="btn" style="width:100%;margin-top:12px">ادامه به پرداخت امن</button><small class="muted">پرداخت مطمئن با درگاه هوشمند بلوپال و کلیه کارت‌های بانکی عضو شتاب</small></aside></form></main>${footer()}`}
function refreshCheckoutTotals(){let method=document.querySelector('[name="shippingMethod"]:checked')?.value||'normal';try{let t=checkoutTotals(method);$('#ship-total').textContent=t.shipping?toman(t.shipping):'رایگان';$('#checkout-totals').querySelector('.total b').textContent=toman(t.total)}catch(e){toast(e.message)}}
function bindForms(){window.__stage2BindForms?.();let f=$('#checkout-form');if(f)f.onsubmit=async e=>{e.preventDefault();if(!f.reportValidity())return;let fd=new FormData(f),phone=st3Num(fd.get('phone')),postal=st3Num(fd.get('postal'));if(!/^09\d{9}$/.test(phone)){toast('شماره موبایل معتبر نیست');return}if(!/^\d{10}$/.test(postal)){toast('کد پستی باید ۱۰ رقم باشد');return}let subtotal=db.cart.reduce((n,i)=>n+(product(i.id)?.price||0)*i.qty,0),discount=0,couponCode='';if(db.coupon?.code){let check=await DemoServices.coupons.validate(db.coupon.code,subtotal);if(!check.valid){db.coupon=null;save();toast(check.reason);render();return}discount=check.discount;couponCode=check.coupon.code}let lines=[];for(let item of db.cart){let p=product(item.id),v=variantFor(p,item.size,item.color);if(!p||!v||v.stock<item.qty){toast(`موجودی ${p?.name||'محصول'} برای این واریانت کافی نیست`);return}lines.push({productId:p.id,name:p.name,sku:v.sku||p.sku,variantId:v.id,size:item.size,color:item.color,variantLabel:`سایز ${item.size}، ${item.color}`,unitPrice:p.price,quantity:item.qty})}let shipMethod=fd.get('shippingMethod')||'normal',shipping;try{shipping=DemoServices.shipping.quote(shipMethod,subtotal)}catch(err){toast(err.message);return}let payMethod=fd.get('paymentMethod')||'bluepal';let now=new Date(),id=`TB-${now.getTime().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,6).toUpperCase()}`,order={id,number:id,customer:fd.get('name').trim(),phone,province:fd.get('province'),city:fd.get('city'),address:fd.get('address').trim(),postal,note:fd.get('note')||'',shippingMethod:shipMethod,paymentMethod:payMethod,itemsList:lines,items:lines.reduce((n,x)=>n+x.quantity,0),subtotal,discount,shipping,total:subtotal-discount+shipping,couponCode,status:'NEW',paymentStatus:'PENDING',trackingCode:`TRK-${now.getTime().toString(36).toUpperCase()}`,createdAt:now.toISOString(),date:new Intl.DateTimeFormat('fa-IR').format(now),timeline:[{status:'NEW',at:now.toISOString()}]};try{let user=db.users.find(x=>st3Num(x.phone)===phone);if(!user){user={id:`customer-${phone}`,name:order.customer,phone,role:'customer',demoAccount:false,isActive:true};await DataRepositories.users.create(user);await DataRepositories.profiles.create({id:`profile-${user.id}`,userId:user.id,displayName:user.name,phone:user.phone})}order.userId=user.id;let customer=db.customers.find(x=>st3Num(x.phone)===phone);if(!customer)await DataRepositories.customers.create({id:phone,name:order.customer,phone,orders:0,total:0,active:true});let addressExists=db.addresses.some(a=>a.userId===user.id&&a.address===order.address&&a.postal===order.postal);if(!addressExists)await DataRepositories.addresses.create({id:st3Id('addr'),userId:user.id,recipient:order.customer,phone,province:order.province,city:order.city,address:order.address,postalCode:order.postal,isDefault:!db.addresses.some(a=>a.userId===user.id)});await DemoServices.orders.create(order);let intent=await DemoServices.payments.createIntent(order,payMethod);save();if(payMethod==='bluepal'){go(`/payment/bluepal/${intent.id}`)}else{go(`/payment/mock/${intent.id}`)}}catch(err){toast(`ثبت سفارش ناموفق بود: ${err.message}`)}};if(path()==='/shop'||path()==='/search'||path().startsWith('/category/')){let sel=$('#shop-sort');if(sel)sel.value=shopState.sort;renderShopResults()}}
async function settleMockPayment(intentId,success){let result=await DemoServices.payments.settle(intentId,success);if(result.success){db.coupon=null;result.order.trackingCode||=`TRK-${Date.now().toString(36).toUpperCase()}`;result.order.timeline||=[{status:'NEW',at:result.order.createdAt}];save();go(`/payment/result/${result.order.id}`)}else{save();go(`/payment/result/${result.order.id}?failed=1`)} }
async function settleBluePalPayment(intentId,success){return settleMockPayment(intentId,success)}
function switchBluePalTab(tab){let bTab=document.getElementById('bluepal-tab-blupay'),pTab=document.getElementById('bluepal-tab-p2p'),bBtn=document.getElementById('tab-btn-blupay'),pBtn=document.getElementById('tab-btn-p2p');if(!bTab||!pTab)return;if(tab==='blupay'){bTab.style.display='block';pTab.style.display='none';if(bBtn){bBtn.style.borderBottom='2px solid #0055ff';bBtn.style.color='#0055ff'}if(pBtn){pBtn.style.borderBottom='2px solid transparent';pBtn.style.color='#64748b'}}else{bTab.style.display='none';pTab.style.display='block';if(pBtn){pBtn.style.borderBottom='2px solid #0055ff';pBtn.style.color='#0055ff'}if(bBtn){bBtn.style.borderBottom='2px solid transparent';bBtn.style.color='#64748b'}}}
function bluepalPaymentPage(intentId){let payment=db.payments.find(x=>x.id===intentId),order=payment&&db.orders.find(x=>x.id===payment.orderId);if(!payment||!order)return notFound();let authority=payment.authority||`BLP-${order.id}`;let cardNum='۶۲۱۹-۸۶۱۹-۲۸۴۱-۷۳۰۵';return `${header()}<main class="page container" style="max-width:760px;margin:30px auto"><div class="auth-card bluepal-gateway" style="background:#ffffff;border:1px solid #cbd5e1;border-radius:20px;padding:28px 24px;box-shadow:0 12px 30px rgba(0,85,255,0.08);text-align:right"><div style="display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e2e8f0;padding-bottom:16px;margin-bottom:20px"><div style="display:flex;align-items:center;gap:12px"><div style="width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#0055ff,#0099ff);color:#fff;display:grid;place-items:center;font-size:22px;font-weight:900;box-shadow:0 4px 12px rgba(0,85,255,0.3)">B</div><div><h2 style="margin:0;font-size:18px;font-weight:800;color:#0f172a;display:flex;align-items:center;gap:8px">درگاه پرداخت هوشمند بلوپال <span style="font-size:12px;font-weight:600;color:#0055ff;background:#eff6ff;padding:2px 8px;border-radius:6px;border:1px solid #bfdbfe">BluePal • BluPay</span></h2><small style="color:#64748b">پرداخت هوشمند و مستقیم متصل به بلوبانک و شبکه بانکی</small></div></div><div style="text-align:left"><span class="badge" style="background:#eafaf1;color:#1e7e34;font-size:11px;display:inline-flex;align-items:center;gap:4px">🔒 ارتباط امن SSL</span><div style="font-size:11px;color:#94a3b8;margin-top:4px">ترمینال: BLUE-94021</div></div></div><div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:16px;margin-bottom:20px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><span style="color:#64748b;font-size:13px">پذیرنده:</span><b style="color:#0f172a">فروشگاه تخصصی کفش طوبی</b></div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><span style="color:#64748b;font-size:13px">شماره سفارش:</span><code style="background:#e2e8f0;padding:2px 8px;border-radius:6px;font-size:12px;font-weight:700">${esc(order.number)}</code></div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><span style="color:#64748b;font-size:13px">شناسه پرداخت بلوپال (Authority):</span><code style="color:#0055ff;font-weight:700">${esc(authority)}</code></div><div style="display:flex;justify-content:space-between;align-items:center;padding-top:10px;border-top:1px dashed #cbd5e1"><span style="color:#0f172a;font-weight:700;font-size:15px">مبلغ قابل پرداخت:</span><b style="color:#0055ff;font-size:20px;font-weight:800">${toman(payment.amount)}</b></div></div><div style="margin-bottom:20px"><div style="display:flex;gap:8px;border-bottom:2px solid #e2e8f0;margin-bottom:16px;flex-wrap:wrap"><button type="button" id="tab-btn-blupay" onclick="switchBluePalTab('blupay')" style="padding:10px 16px;background:none;border:none;border-bottom:2px solid #0055ff;margin-bottom:-2px;font-weight:700;color:#0055ff;cursor:pointer;font-family:inherit">⚡ روش اول: پرداخت سریع با اپلیکیشن بلوبانک (BluPay)</button><button type="button" id="tab-btn-p2p" onclick="switchBluePalTab('p2p')" style="padding:10px 16px;background:none;border:none;border-bottom:2px solid transparent;margin-bottom:-2px;font-weight:600;color:#64748b;cursor:pointer;font-family:inherit">💳 روش دوم: کارت به کارت خودکار هوشمند</button></div><div id="bluepal-tab-blupay" style="background:#f0f7ff;border:1px solid #bfdbfe;border-radius:14px;padding:20px"><div style="display:flex;align-items:center;gap:12px;margin-bottom:12px"><span style="font-size:24px">📲</span><div><b style="color:#1e3a8a;font-size:14px">پرداخت با یک لمس ویژه کاربران بلوبانک</b><p style="margin:2px 0 0;color:#3b82f6;font-size:12px">بدون نیاز به وارد کردن شماره کارت ۱۶ رقمی، تاریخ انقضا و رمز دوم پویا</p></div></div><div style="background:#ffffff;border:1px solid #dbeafe;border-radius:10px;padding:12px;margin:12px 0;display:flex;align-items:center;justify-content:space-between"><span style="color:#475569;font-size:12px">شماره همراه شما در بلوبانک:</span><b style="color:#1e293b;direction:ltr">${esc(order.phone)}</b></div><div style="display:flex;align-items:center;gap:8px;margin-top:14px"><button class="btn" style="flex:1;background:#0055ff;box-shadow:0 4px 14px rgba(0,85,255,0.3)" onclick="settleBluePalPayment('${payment.id}',true)">تأیید پرداخت و کسر از حساب بلوبانک</button></div></div><div id="bluepal-tab-p2p" style="display:none;background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:20px"><p style="margin-top:0;font-size:13px;color:#475569">مبلغ سفارش را به شماره کارت اختصاصی بلوبانک واریز کنید؛ ربات وب‌سرویس بلوپال به محض واریز، تراکنش را تأیید می‌کند.</p><div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:14px;margin-bottom:12px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="font-size:12px;color:#64748b">شماره کارت مقصد (بلوبانک):</span><div style="display:flex;align-items:center;gap:6px"><b style="font-size:15px;direction:ltr;letter-spacing:1px;color:#0f172a">${cardNum}</b><button type="button" class="btn small outline" onclick="navigator.clipboard?.writeText('${cardNum.replaceAll('-','')}');toast('شماره کارت کپی شد')">کپی</button></div></div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="font-size:12px;color:#64748b">به نام:</span><b style="color:#0f172a">کفش طوبی (فروشگاه آنلاین)</b></div><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:12px;color:#64748b">شناسه واریز اختصاصی:</span><code style="background:#e0f2fe;color:#0284c7;padding:2px 8px;border-radius:4px;font-weight:700">${esc(authority)}</code></div></div><button class="btn" style="width:100%;background:#0055ff" onclick="settleBluePalPayment('${payment.id}',true)">من کارت به کارت کردم (بررسی و ثبت آنی)</button></div></div><div style="display:flex;align-items:center;justify-content:space-between;margin-top:16px;padding-top:16px;border-top:1px solid #f1f5f9"><button class="btn danger-button" style="background:#ef4444" onclick="settleBluePalPayment('${payment.id}',false)">انصراف و لغو تراکنش</button><a class="text-link" href="/cart" style="font-size:13px;color:#64748b">بازگشت به سبد خرید</a></div></div></main>${footer()}`}
function mockPaymentPage(intentId){let payment=db.payments.find(x=>x.id===intentId),order=payment&&db.orders.find(x=>x.id===payment.orderId);if(!payment||!order)return notFound();return `${header()}<main class="page container"><div class="auth-card mock-gateway"><span class="badge" style="background:#eaf5ea;color:#2e7d32">درگاه پرداخت الکترونیک شاپرک</span><h1>پرداخت امن سفارش</h1><p>شماره سفارش: <b>${esc(order.number)}</b></p><div class="summary-line"><span>مبلغ قابل پرداخت</span><b>${toman(payment.amount)}</b></div><div class="notice">تراکنش در بستر امن شبکه شاپرک با پروتکل رمزنگاری SSL انجام می‌شود.</div><button class="btn" onclick="settleMockPayment('${payment.id}',true)">تأیید پرداخت و صدور فاکتور</button><button class="btn danger-button" onclick="settleMockPayment('${payment.id}',false)">انصراف و بازگشت به سبد خرید</button><a class="text-link" href="/cart">انصراف و بازگشت</a></div></main>${footer()}`}
function paymentResult(orderId){let o=db.orders.find(x=>x.id===orderId);if(!o)return notFound();let ok=o.paymentStatus==='PAID';let isBluePal=o.paymentMethod==='bluepal'||(o.paymentRef&&o.paymentRef.startsWith('BLP-'));return `${header()}<main class="page container" style="max-width:680px;margin:30px auto"><div class="auth-card" style="text-align:center;padding:32px 24px;border-radius:18px"><div class="payment-result-icon ${ok?'success':'failure'}">${ok?'✓':'×'}</div><h1 style="margin:16px 0 8px;font-size:22px">${ok?'پرداخت با موفقیت انجام شد':'پرداخت ناموفق بود'}</h1><div style="margin-bottom:20px">${isBluePal?`<span class="badge" style="background:#eff6ff;color:#0055ff;border:1px solid #bfdbfe;font-size:12px;padding:4px 12px;border-radius:8px">پرداخت هوشمند بلوپال (بلوبانک)</span>`:`<span class="badge" style="background:#f1f5f9;color:#475569;font-size:12px;padding:4px 12px;border-radius:8px">درگاه پرداخت الکترونیک شاپرک</span>`}</div><div class="summary-line" style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f1f5f9"><span>شماره سفارش:</span><b>${esc(o.number)}</b></div><div class="summary-line" style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f1f5f9"><span>کد رهگیری:</span><b>${esc(o.trackingCode)}</b></div>${o.paymentRef?`<div class="summary-line" style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f1f5f9"><span>شماره مرجع بانکی:</span><code style="color:#0055ff;font-weight:700">${esc(o.paymentRef)}</code></div>`:''}<div class="summary-line" style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f1f5f9"><span>مبلغ پرداختی:</span><b>${toman(o.total)}</b></div><div class="summary-line" style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f1f5f9"><span>وضعیت:</span><b style="color:${ok?'#16a34a':'#dc2626'}">${ok?'پرداخت شده و ثبت در انبار':'ناموفق'}</b></div>${!ok?'<div class="notice error-notice" style="margin:16px 0">موجودی سبد خرید شما حفظ شده و می‌توانید دوباره اقدام کنید.</div>':''}<div style="display:flex;gap:10px;justify-content:center;margin-top:24px"><a class="btn" href="/tracking">پیگیری سفارش</a>${ok?'<a class="btn outline" href="/shop">ادامه خرید از فروشگاه</a>':'<a class="btn outline" href="/checkout">تلاش دوباره برای پرداخت</a>'}</div></div></main>${footer()}`}
function tracking(){return `${header()}<main class="page container"><form class="auth-card" onsubmit="event.preventDefault();trackOrder(this)"><h1>پیگیری سفارش</h1><p>شماره سفارش و موبایل ثبت‌شده را وارد کنید.</p><div class="field"><label>شماره سفارش</label><input name="number" required placeholder="TB-..."></div><div class="field"><label>شماره موبایل</label><input name="phone" required pattern="[0-9۰-۹٠-٩]{11}" placeholder="09123456789"></div><button class="btn">پیگیری سفارش</button><div id="tracking-result"></div></form></main>${footer()}`}
function trackOrder(form){let fd=new FormData(form),number=fd.get('number').trim().toLowerCase(),phone=st3Num(fd.get('phone')),o=db.orders.find(x=>(x.number||x.id).toLowerCase()===number&&st3Num(x.phone)===phone);if(!o){$('#tracking-result').innerHTML='<div class="notice error-notice">سفارش با این شماره و موبایل پیدا نشد.</div>';return}let states=['NEW','CONFIRMED','PROCESSING','SHIPPED','DELIVERED'],at=states.indexOf(o.status);$('#tracking-result').innerHTML=`<div class="tracking-card"><h3>${esc(o.number)}</h3><p>${esc(o.date||'')} · مبلغ ${toman(o.total)}</p><p>پرداخت: <b>${o.paymentStatus==='PAID'?'پرداخت شده':o.paymentStatus==='FAILED'?'ناموفق':'در انتظار پرداخت'}</b></p><p>کد رهگیری ارسال: <b>${esc(o.trackingCode||'پس از ارسال ثبت می‌شود')}</b></p><div class="timeline">${states.map((s,i)=>`<div class="timeline-step ${i<=at?'done':''}"><i>${i<=at?'✓':i+1}</i><span>${ST3_STATUS[s]}</span></div>`).join('')}</div><h4>اقلام سفارش</h4>${(o.itemsList||[]).map(i=>`<div class="summary-line"><span>${esc(i.name)} · ${esc(i.variantLabel)} × ${i.quantity}</span><b>${toman(i.unitPrice*i.quantity)}</b></div>`).join('')}</div>`}
function reviewModal(productId){if(!db.currentUser||db.currentUser.role!=='customer'){toast('برای ثبت دیدگاه ابتدا با حساب مشتری وارد شوید');go('/login');return}let p=product(productId);showModal(`<form onsubmit="event.preventDefault();submitReview(this,'${productId}')"><h3>ثبت دیدگاه برای ${esc(p?.name||'محصول')}</h3><div class="field"><label>امتیاز</label><select name="rating"><option value="5">۵ ستاره</option><option value="4">۴ ستاره</option><option value="3">۳ ستاره</option><option value="2">۲ ستاره</option><option value="1">۱ ستاره</option></select></div><div class="field"><label>متن نظر</label><textarea name="text" required minlength="5"></textarea></div><button class="btn">ارسال برای بررسی مدیر</button></form>`)}
async function submitReview(f,id){let p=product(id);await DemoServices.reviews.submit({name:db.currentUser.name,userId:db.currentUser.id,productId:id,product:p?.name||'',rating:Number(f.elements.rating.value),text:f.elements.text.value.trim()});closeModal();toast('دیدگاه ثبت شد و پس از بررسی نمایش داده می‌شود')}
async function reviewStatus(id,status){let review=db.reviews.find(x=>x.id===id)||db.reviews[id];if(!review)return;await DataRepositories.reviews.update(review.id,{status});render();toast('وضعیت دیدگاه ذخیره شد')}
async function saveProduct(f,id){let fd=new FormData(f),sizes=[...new Set(fd.get('sizes').split(',').map(x=>x.trim()).filter(Boolean))],colors=[...new Set(fd.get('colors').split(',').map(x=>x.trim()).filter(Boolean))];if(!sizes.length||!colors.length){toast('حداقل یک سایز و رنگ لازم است');return}let images=fd.get('images').split(/\n/).map(x=>x.trim()).filter(Boolean);if(images.some(x=>!isLocalAsset(x))){toast('تصویر محصول باید مسیر محلی یا آدرس معتبر تصویری باشد');return}let rows=[...$('#variant-editor').querySelectorAll('tr')],variants=rows.map(r=>({id:variantKey(r.querySelector('.v-size').value,r.querySelector('.v-color').value),size:r.querySelector('.v-size').value,color:r.querySelector('.v-color').value,sku:r.querySelector('.v-sku').value.trim(),stock:Math.max(0,Number(r.querySelector('.v-stock').value)||0)}));if(variants.length!==sizes.length*colors.length||variants.some(v=>!sizes.includes(v.size)||!colors.includes(v.color))){toast('جدول واریانت‌ها را بازسازی کنید');return}let old=id?product(id):null,now=new Date().toISOString(),name=fd.get('name').trim(),slug=fd.get('slug').trim()||v2slug(name),obj={...(old||{}),id:id||st3Id('prd'),name,slug,category:fd.get('category'),price:Number(fd.get('price')),oldPrice:Number(fd.get('oldPrice'))||0,discountPercent:Number(fd.get('oldPrice'))>Number(fd.get('price'))?Math.round((Number(fd.get('oldPrice'))-Number(fd.get('price')))*100/Number(fd.get('oldPrice'))):0,sku:fd.get('sku').trim(),brand:fd.get('brand').trim(),sizes,colors,variants,stock:variants.reduce((n,v)=>n+v.stock,0),images,shortDesc:fd.get('shortDesc').trim(),longDesc:fd.get('longDesc').trim(),desc:fd.get('longDesc').trim(),features:fd.get('features').split('\n').map(x=>x.trim()).filter(Boolean),specifications:Object.fromEntries(fd.get('specifications').split('\n').map(x=>x.split(':')).filter(x=>x.length>1).map(x=>[x[0].trim(),x.slice(1).join(':').trim()])),featured:f.elements.featured.checked,bestSeller:f.elements.bestSeller.checked,active:f.elements.active.checked,image:old?.image??Math.floor(Math.random()*4),createdAt:old?.createdAt||now,updatedAt:now};if(db.products.some(x=>x.id!==obj.id&&x.slug===slug)){toast('این slug قبلاً استفاده شده است');return}if(db.products.some(x=>x.id!==obj.id&&x.sku===obj.sku)){toast('SKU باید یکتا باشد');return}if(id)await DemoServices.products.update(id,obj);else await DemoServices.products.create(obj);closeModal();render();toast('محصول با موفقیت در پایگاه داده ذخیره شد')}
async function deleteEntity(key,id,field='id'){let repo=DataRepositories[key];if(!repo){toast('مورد پیدا نشد');return}showModal(`<h3>از حذف این مورد مطمئن هستید؟</h3><p>این تغییر در پایگاه داده اعمال خواهد شد.</p><button class="btn danger-button" id="confirm-delete">حذف قطعی</button> <button class="btn outline" onclick="closeModal()">انصراف</button>`);$('#confirm-delete').onclick=async()=>{try{if(key==='products')await DemoServices.products.remove(id);else await repo.delete(id);closeModal();render();toast('رکورد حذف شد')}catch(e){toast(e.message)}}}
async function saveCategory(f,id){let category={id:f.elements.slug.value.trim()||id||st3Id('cat'),slug:f.elements.slug.value.trim()||v2slug(f.elements.name.value),name:f.elements.name.value.trim(),icon:f.elements.icon.value.trim(),active:f.elements.active.checked,sortOrder:db.categories.length};if(id)await DataRepositories.categories.update(id,category);else await DemoServices.categories.create(category);closeModal();render();toast('دسته‌بندی ذخیره شد')}
async function customerToggle(index){let c=db.customers[index];if(!c)return;await DemoServices.customers.update(c.id||c.phone,{active:!c.active});render();toast('وضعیت مشتری ذخیره شد')}
async function toggleProduct(id){let p=product(id);if(!p)return;await DemoServices.products.update(id,{active:!p.active});render();toast(p.active?'محصول پیش‌نویس شد':'محصول منتشر شد')}
function couponsAdmin(){return `<div class="admin-title-row"><h1>کدهای تخفیف</h1><button class="btn small" onclick="couponModal()">＋ کد تخفیف</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>کد</th><th>نوع / مقدار</th><th>حداقل خرید</th><th>تاریخ</th><th>استفاده</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${db.coupons.map(c=>`<tr><td><b>${esc(c.code)}</b></td><td>${esc(c.type)} · ${c.type==='درصدی'?`${c.amount}٪`:toman(c.amount)}</td><td>${toman(c.min||0)}</td><td>${esc(c.start||'—')} تا ${esc(c.end||'—')}</td><td>${c.used||0} / ${c.limit||'∞'}</td><td>${c.active?'فعال':'غیرفعال'}</td><td><button class="action" onclick="couponModal('${c.code}')">ویرایش</button> <button class="action" onclick="couponToggle('${c.code}')">تغییر وضعیت</button> <button class="action danger" onclick="deleteEntity('coupons','${c.id||c.code}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="7">کد تخفیفی موجود نیست.</td></tr>'}</tbody></table></div>`}
function couponModal(code){let c=db.coupons.find(x=>x.code===code)||{code:'',type:'درصدی',amount:'',min:0,start:'',end:'',limit:50,used:0,active:true};showModal(`<form onsubmit="event.preventDefault();saveCoupon(this,'${code||''}')"><div class="form-grid"><div class="field"><label>کد تخفیف</label><input name="code" required value="${esc(c.code)}" ${code?'readonly':''}></div><div class="field"><label>نوع تخفیف</label><select name="type"><option ${c.type==='درصدی'?'selected':''}>درصدی</option><option ${c.type==='مبلغ ثابت'?'selected':''}>مبلغ ثابت</option></select></div><div class="field"><label>مقدار</label><input name="amount" type="number" min="1" required value="${c.amount}"></div><div class="field"><label>حداقل مبلغ سفارش</label><input name="min" type="number" min="0" value="${c.min||0}"></div><div class="field"><label>شروع (شمسی YYYY/MM/DD)</label><input name="start" value="${esc(c.start||'')}"></div><div class="field"><label>پایان</label><input name="end" value="${esc(c.end||'')}"></div><div class="field"><label>حداکثر استفاده</label><input name="limit" type="number" min="1" value="${c.limit||50}"></div><div class="field"><label><input type="checkbox" name="active" ${c.active?'checked':''}> فعال</label></div><button class="btn">ذخیره کد</button></div></form>`)}
async function saveCoupon(f,id){let code=f.elements.code.value.trim().toUpperCase(),coupon={id:id||code,code,type:f.elements.type.value,amount:Number(f.elements.amount.value),start:f.elements.start.value,end:f.elements.end.value,min:Number(f.elements.min.value)||0,limit:Number(f.elements.limit.value)||0,used:id?(db.coupons.find(x=>x.code===id)?.used||0):0,active:f.elements.active.checked};if(!id&&db.coupons.some(x=>x.code===code)){toast('این کد از قبل وجود دارد');return}if(id)await DataRepositories.coupons.update(id,coupon);else await DataRepositories.coupons.create(coupon);closeModal();render();toast('کد تخفیف ذخیره شد')}
async function couponToggle(code){let c=db.coupons.find(x=>x.code===code);if(c){await DataRepositories.coupons.update(c.id||c.code,{active:!c.active});render()}}
function orderDetails(id){let o=db.orders.find(x=>x.id===id);if(!o)return;showModal(`<h2>سفارش ${esc(o.number||o.id)}</h2><div class="notice">مشتری: ${esc(o.customer)} · ${esc(o.phone)}<br>نشانی: ${esc(o.province||'')}، ${esc(o.city||'')}، ${esc(o.address||'')} · ${esc(o.postal||'—')}<br>تاریخ: ${esc(o.date||'')}<br>کد پیگیری: <b>${esc(o.trackingCode||'—')}</b></div><h3>اقلام سفارش</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>محصول</th><th>واریانت</th><th>قیمت واحد</th><th>تعداد</th><th>جمع</th></tr></thead><tbody>${(o.itemsList||[]).map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.variantLabel||`سایز ${i.size}، ${i.color}`)}</td><td>${toman(i.unitPrice)}</td><td>${i.quantity}</td><td>${toman(i.unitPrice*i.quantity)}</td></tr>`).join('')}</tbody></table></div><div class="summary-line"><span>جمع اقلام</span><b>${toman(o.subtotal??o.total)}</b></div><div class="summary-line"><span>تخفیف</span><b>− ${toman(o.discount)}</b></div><div class="summary-line"><span>هزینه ارسال</span><b>${toman(o.shipping)}</b></div><div class="summary-line total"><span>مبلغ نهایی</span><b>${toman(o.total)}</b></div><p>وضعیت: ${ST3_STATUS[o.status]||o.status} · پرداخت: ${o.paymentStatus==='PAID'?'پرداخت شده':o.paymentStatus==='FAILED'?'ناموفق':'در انتظار پرداخت'}</p>`)}
async function orderStatus(id,status){let o=db.orders.find(x=>x.id===id);if(!o)return;let timeline=[...(o.timeline||[]),{status,at:new Date().toISOString()}];if(status==='CANCELLED'&&o.status!=='CANCELLED'&&o.inventoryDeducted&&!o.inventoryRestocked){for(let line of o.itemsList||[]){let p=product(line.productId),v=p?.variants.find(x=>x.id===line.variantId)||variantFor(p,line.size,line.color);if(v){v.stock+=line.quantity;p.stock=totalStock(p);await DataRepositories.products.update(p.id,p)}}o.inventoryRestocked=true}await DemoServices.orders.update(id,{status,timeline,updatedAt:new Date().toISOString(),...(status==='SHIPPED'?{trackingCode:o.trackingCode||`TRK-${Date.now().toString(36).toUpperCase()}`}:{})});render();toast('وضعیت سفارش ذخیره شد')}
function render(){document.body.classList.remove('admin-body');let p=path(),html;if(p==='/')html=(typeof window.home==='function'?window.home():home());else if(p==='/shop'||p==='/search')html=(typeof window.shop==='function'?window.shop():shop());else if(p.startsWith('/category/')){let slug=decodeURIComponent(p.split('/')[2]),c=db.categories.find(x=>x.id===slug||x.slug===slug||x.name===slug);html=(typeof window.shop==='function'?window.shop(c?c.id:slug):(c?shop(c.id):shop()))}else if(p.startsWith('/product/'))html=(typeof window.detail==='function'?window.detail(decodeURIComponent(p.split('/')[2])):detail(decodeURIComponent(p.split('/')[2])));else if(p==='/cart')html=(typeof window.cartPage==='function'?window.cartPage():cartPage());else if(p==='/checkout')html=(typeof window.checkout==='function'?window.checkout():checkout());else if(p==='/login')html=login();else if(p==='/account')html=account();else if(p==='/account/orders')html=ordersPage();else if(p==='/tracking')html=(typeof window.tracking==='function'?window.tracking():tracking());else if(p.startsWith('/payment/bluepal/'))html=bluepalPaymentPage(p.split('/')[3]);else if(p.startsWith('/payment/mock/'))html=mockPaymentPage(p.split('/')[3]);else if(p.startsWith('/payment/result/'))html=paymentResult(decodeURIComponent(p.split('/')[3]));else if(p==='/about'||p==='/contact'||p==='/terms'||p==='/privacy')html=(typeof window.contentPage==='function'?window.contentPage(p.slice(1)):contentPage(p.slice(1)));else if(p==='/admin'||p.startsWith('/admin/')){document.body.classList.remove('admin-body');html=admin()}else html=notFound();$('#app').innerHTML=html;bindForms();window.scrollTo(0,0)}
window.__stage3AdminSection=adminSection;window.__stage3BindForms=bindForms;window.__stage3Render=render;window.switchBluePalTab=switchBluePalTab;window.settleBluePalPayment=settleBluePalPayment;window.bluepalPaymentPage=bluepalPaymentPage;
if(typeof window!=="undefined"&&!document.querySelector?.('script[src*="stage4.js"]')){render();}
